export function clampInteger(value, fallback, min, max) {
  // Convert value to a base‑10 integer. Accept number inputs or strings.
  const parsed = Number.parseInt(value, 10);
  // If parsing fails (NaN), return the provided fallback.
  if (!Number.isFinite(parsed)) return fallback;
  // Clamp the parsed value between min and max (inclusive).
  return Math.min(max, Math.max(min, parsed));
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { clampInteger } from '../src/lib.mjs';

// Helper to simplify calls
function run(val, fallback, min, max, expected){
  const result = clampInteger(val, fallback, min, max);
  assert.equal(result, expected, `clampInteger(${JSON.stringify(val)},${fallback},${min},${max}) → ${result}, expected ${expected}`);
}

test('clampInteger parses numeric strings and clamps inclusively', t => {
  run('8', -1, 1, 10, 8);
  run('0', -1, 1, 10, 1); // below min
  run('-5', -1, -10, 0, -5); // within
  run('-15', -1, -10, 0, -10); // below min
  run('20', -1, 1, 10, 10); // above max
});

test('clampInteger handles explicit zeros and fallback', t => {
  run(0, -1, 1, 10, 1);
  run('0', -1, 1, 10, 1);
  run('', -1, 1, 10, -1); // empty string -> fallback
  run('  ', -1, 1, 10, -1); // whitespace
  run('abc', -1, 1, 10, -1); // invalid string
  run(null, 5, 1, 10, 5); // null -> fallback
  run(undefined, 5, 1, 10, 5); // undefined -> fallback
});

import path from 'node:path';

/**
 * Resolve a relative to absolute path strictly within a given workspace root.
 *
 * @param {string} root - The root directory of the workspace.
 * @param {string} value - The path to resolve.
 * @returns {string} The absolute resolved path.
 * @throws {Error} If `value` is absolute or escapes the workspace root.
 */
export function resolveRelative(root, value) {
  // Guard against absolute paths – user can intentionally provide them only if they refer to root.
  if (path.isAbsolute(value)) {
    throw new Error(`Absolute paths are forbidden: ${value}`);
  }

  // Resolve the path relative to the workspace root. Since we are not touching the fs,
  // path.resolve behaves purely as a string manipulation.
  const resolvedAbsolute = path.resolve(root, value);

  // Determine the relative path from the root to the resolved path.
  const relativeFromRoot = path.relative(root, resolvedAbsolute);

  // If the relative path begins with '..' then the resolved path is outside the root.
  const components = relativeFromRoot.split(path.sep).filter(Boolean);
  if (components[0] === '..' || relativeFromRoot.startsWith('..' + path.sep) || relativeFromRoot === '..') {
    throw new Error(`Path escapes the workspace: ${value}`);
  }

  return resolvedAbsolute;
}

import { resolveRelative } from '../src/lib.mjs';

function test(name, root, value, expected) {
  try {
    const result = resolveRelative(root, value);
    console.log(name, '→', result, 'expected:', expected, result===expected ? '✓' : '✗');
  } catch (e) {
    console.log(name, '→', 'Error:', e.message);
  }
}

const root = "/tmp/workspace";

// Normal relative
test('1', root, 'subdir/file.txt', '/tmp/workspace/subdir/file.txt');
// absolute path should error
test('2', root, '/etc/passwd', null);
// escape via .. should error
test('3', root, '../outside.txt', null);
// empty string -> root
test('4', root, '', root);
// single dot -> root
test('5', root, '.', root);
// dot-notation
test('6', root, './a/../b', '/tmp/workspace/b');
